n CloudWatch logging option updates. (structure) Describes CloudWatch logging option updates. CloudWatchLoggingOptionId -&gt; (string) [required] ID of the CloudWatch logging option to update Constraints: o min: 1 o max: 50 o pattern: [a-zA-Z0-9_.-]+ LogStreamARNUpdate -&gt; (string) ARN of the CloudWatch log to receive application mes- sages. Constraints: o min: 1 o max: 2048 o pattern: arn:.* RoleARNUpdate -&gt; (string) IAM ARN of the role to use to send application messages. Note: To write application messages to CloudWatch, the IAM role used must have the PutLogEvents policy action enabled. Constraints: o min: 1 o max: 2048 o pattern: arn:aws:iam::\d{12}:role/?[a-zA-Z_0-9+=,.@\-_/]+ JSON Syntax: { "InputUpdates": [ { "InputId": "string", "NamePrefixUpdate": "string", "InputProcessingConfigurationUpdate": { "InputLambdaProcessorUpdate": { "ResourceARNUpdate": "string", "RoleARNUpdate": "string" } }, "KinesisStreamsInputUpdate": { "ResourceARNUpdate": "string", "RoleARNUpdate": "string" }, "KinesisFirehoseInputUpdate": { "ResourceARNUpdate": "string", "RoleARNUpdate": "string" }, "InputSchemaUpdate": { "RecordFormatUpdate": { "RecordFormatType": "JSON"|"CSV", "MappingParameters": { "JSONMappingParameters": { "RecordRowPath": "string" }, "CSVMappingParameters": { "RecordRowDelimiter": "string", "RecordColumnDelimiter": "string" } } }, "RecordEncodingUpdate": "string", "RecordColumnUpdates": [ { "Name": "string", "Mapping": "string", "SqlType": "string" } ... ] }, "InputParallelismUpdate": { "CountUpdate": integer } } ... ], "ApplicationCodeUpdate": "string", "OutputUpdates": [ { "OutputId": "string", "NameUpdate": "string", "KinesisStreamsOutputUpdate": { "ResourceARNUpdate": "string", "RoleARNUpdate": "string" }, "KinesisFirehoseOutputUpdate": { "ResourceARNUpdate": "string", "RoleARNUpdate": "string" }, "LambdaOutputUpdate": { "ResourceARNUpdate": "string", "RoleARNUpdate": "string" }, "DestinationSchemaUpdate": { "RecordFormatType": "JSON"|"CSV" } } ... ], "ReferenceDataSourceUpdates": [ { "ReferenceId": "string", "TableNameUpdate": "string", "S3ReferenceDataSourceUpdate": { "BucketARNUpdate": "string", "FileKeyUpdate": "string", "ReferenceRoleARNUpdate": "string" }, "ReferenceSchemaUpdate": { "RecordFormat": { "RecordFormatType": "JSON"|"CSV", "MappingParameters": { "JSONMappingParameters": { "RecordRowPath": "string" }, "CSVMappingParameters": { "RecordRowDelimiter": "string", "RecordColumnDelimiter": "string" } } }, "RecordEncoding": "string", "RecordColumns": [ { "Name": "string", "Mapping": "string", "SqlType": "string" } ... ] } } ... ], "CloudWatchLoggingOptionUpdates": [ { "CloudWatchLoggingOptionId": "string", "LogStreamARNUpdate": "string", "RoleARNUpdate": "string" } ... ] }
    /// </summary>
    [CliOption("--application-update")]
    public string? ApplicationUpdate { get; private init; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

